/* arkcc C startup for STM32F401xE.
 * __arkcc_init_globals (auto-generated by arkcc) initializes all .data
 * globals (SystemCoreClock, AHBPrescTable, uwTickFreq, etc.) and zeros .bss.
 * Reset_Handler just calls it, then SystemInit and main.
 * Default_Handler loops forever (catches unregistered IRQs). */

extern void SystemInit(void);
extern int main(void);

void Reset_Handler(void) {
    /* __arkcc_init_globals is emitted by arkcc and initializes all globals
     * with their declared initializers, then zeros .bss. Do NOT manually
     * zero BSS here - that would wipe the just-initialized .data values
     * (e.g. uwTickFreq=1 would become 0, causing divide-by-zero in HAL_InitTick). */
    SystemInit();
    main();
    while (1) {}
}

void Default_Handler(void) {
    while (1) {}
}
